#include<bits/stdc++.h>
using namespace std;
const int maxn=10015,maxm=1000005;
int fath[maxn],cost[15],vis[15];
pair<int,pair<int,int> >edge[maxm];
inline int read(){
    int num=0; char ch=getchar();
    while(ch<'0' or ch>'9') ch=getchar();
    while(ch>='0' and ch<='9'){
        num=(num<<3)+(num<<1)+(ch^48);
        ch=getchar();
    }
    return num;
}
inline int find(int u){
    return fath[u]==u?u:fath[u]=find(fath[u]);
}
int main(){
    int n=read(),m=read(),k=read();
    for(int i=1;i<=m;i++){
        int u=read(),v=read();
        edge[i]=make_pair(read(),make_pair(u,v));
    }
    sort(edge+1,edge+1+m);
    for(int i=1;i<=n;i++) fath[i]=i;
    int tot=0;
    for(int i=1;i<=m;i++){
        int fu=find(edge[i].second.first),fv=find(edge[i].second.second);
        if(fu!=fv){
            fath[fv]=fu;
            edge[++tot]=edge[i];
            if(tot==n-1) break;
        }
    }
    for(int i=1;i<=k;i++){
        cost[i]=read();
        for(int j=1;j<=n;j++){
            edge[++tot]=make_pair(read(),make_pair(j,n+i));
        }
    }
    sort(edge+1,edge+1+tot);
    long long ans=1e18;
    for(int stat=0;stat<(1<<k);stat++){
        long long now=0;
        int num=0;
        for(int i=1;i<=k;i++){
            if((stat>>(i-1))&1){
                ++num,vis[i]=1;
                now+=cost[i];
            }
            else vis[i]=0;
        }
        for(int i=1;i<=n+k;i++) fath[i]=i;
        int need=n+num-1;
        for(int i=1;i<=tot;i++){
            int u=edge[i].second.first,v=edge[i].second.second;
            if(v>n and !vis[v-n]) continue;
            int fu=find(u),fv=find(v);
            if(fu!=fv){
                fath[fv]=fu;
                now+=edge[i].first;
                if(!(--need)) break;
            }
        }
        if(!need) ans=min(ans,now);
    }
    cout<<ans<<"\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
constexpr int M = 1000005, N = 10015;
int n, up;
struct node {
    int u, v, w;
} b[M];
node a[10][N], e[1 << 10][N];
bool cmp(const node &x, const node &y) {
    return x.w < y.w;
}
int c[10], sz[1 << 10];
ll sum[1 << 10];
int f[N];
inline int find(int x) {
    return f[x] == x ? x : f[x] = find(f[x]);
}
inline bool merge(int u, int v) {
    u = find(u), v = find(v);
    if (u == v)
        return 0;
    f[u] = v;
    return 1;
}
bool vis[N];
vector<int> adj[N]; 
void dfs(int p) {
    vis[p] = 1;
    for (int v : adj[p])
        if (!vis[v])
            dfs(v);
}
inline ll work(int m, int cc, int id, node *e) {
    ll res = 0;
    int k = 0;
    for (int i = 1; i <= m; i++) {
        if (b[i].u == id) {
            int x = b[i].v;
            if (vis[x])
                continue;
            dfs(x);
        } else {
            int x = b[i].u, y = b[i].v;
            if (vis[x] && vis[y])
                continue;
            if (vis[x])
                dfs(y);
            else if (vis[y])
                dfs(x);
            else
                adj[x].emplace_back(y), adj[y].emplace_back(x);
        }
        res += (e[++k] = b[i]).w;
        if (k == cc)
            break;
    }
    for (int i = 1; i <= up; i++)
        adj[i].clear();
    memset(vis + 1, 0, sizeof(bool) * up);
    return res;
}
int main() {
    cin.tie(0)->sync_with_stdio(0);
    int m, k;
    cin >> n >> m >> k;
    up = n + k;
    for (int i = 1; i <= m; i++)
        cin >> b[i].u >> b[i].v >> b[i].w;
    sort(b + 1, b + m + 1, cmp);
    for (int i = 1; i <= up; i++)
        f[i] = i;
    int k0 = 0;
    ll res = 0;
    for (int i = 1; i <= m; i++) {
        if (merge(b[i].u, b[i].v))
            res += (e[0][++k0] = b[i]).w;
        if (k0 == n - 1)
            break;
    }
    sz[0] = n - 1;
    for (int i = 0; i < k; i++) {
        cin >> c[i];
        for (int j = 1; j <= n; j++) {
            cin >> a[i][j].w;
            a[i][j].u = n + i + 1, a[i][j].v = j;
        }
        sort(a[i] + 1, a[i] + n + 1, cmp);
    }
    for (int i = 1; i < (1 << k); i++) {
        int x = __builtin_ctz(i), to = i & (i - 1);
        sz[i] = sz[to] + 1, sum[i] = sum[to] + c[x];
        merge(e[to] + 1, e[to] + sz[to] + 1, a[x] + 1, a[x] + n + 1, b + 1, cmp); 
        res = min(res, work(sz[to] + n, sz[i], x+n+1, e[i]) + sum[i]);
    }
    cout << res << '\n';
    return 0;
}
